SELECT CASE WHEN YEAR(s.opened_date) < 2024 THEN 'before_2024' WHEN YEAR(s.opened_date) = 2024 THEN '2024' ELSE 'after_2024' END AS opened_cohort, SUM(ss.revenue) AS total_revenue FROM store_sales ss LEFT JOIN stores s ON s.id = ss.store_id WHERE ss.revenue <= 3800 GROUP BY CASE WHEN YEAR(s.opened_date) < 2024 THEN 'before_2024' WHEN YEAR(s.opened_date) = 2024 THEN '2024' ELSE 'after_2024' END ORDER BY total_revenue DESC, opened_cohort DESC;
